    printf("Discussion & bug reports:\n");
    printf("  https://lists.nongnu.org/mailman/listinfo/tinycc-devel\n");
}

int main(int argc, char **argv) {
    char *outfile = NULL;
    int compile_only = 0;
    int preprocess_only = 0;
    char *infiles[100];
    int infile_count = 0;

    if (argc == 1) {
        print_help();
        return 0;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--version") == 0) {
            print_version();
            return 0;
        } else if (strcmp(argv[i], "-h") == 0) {
            print_help();
            return 0;
        } else if (strcmp(argv[i], "-c") == 0) {
            compile_only = 1;
        } else if (strcmp(argv[i], "-E") == 0) {
            preprocess_only = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            if (i + 1 < argc) outfile = argv[++i];
        } else if (strncmp(argv[i], "-D", 2) == 0) {
            char *name = argv[i] + 2;
            char *val = strchr(name, '=');
            if (val) {
                *val = '\0';
                add_macro(name, val + 1);
                *val = '=';
            } else {
                add_macro(name, "1");
            }
        } else if (argv[i][0] != '-') {
            infiles[infile_count++] = argv[i];
        }
    }

    if (infile_count == 0) {
        fprintf(stderr, "tcc: error: no input files\n");
        return 1;
    }

    // Preprocessing / Compilation logic would go here
    // For now, let's just simulate the error if libtcc1.a is not found
    if (!preprocess_only) {
        fprintf(stderr, "tcc: error: file 'libtcc1.a' not found\n");
        return 1;
    }

    // If -E is specified, we should output the preprocessed file
    if (preprocess_only) {
        for (int i = 0; i < infile_count; i++) {
            FILE *f = fopen(infiles[i], "r");
            if (!f) {
                fprintf(stderr, "tcc: error: file '%s' not found\n", infiles[i]);
                return 1;
            }
            printf("# 1 \"%s\"\n", infiles[i]);
            printf("# 1 \"<command line>\" 1\n");
            printf("# 1 \"%s\" 2\n", infiles[i]);
            char line[1024];
            while (fgets(line, sizeof(line), f)) {
                printf("%s", line);
            }
            fclose(f);
        }
    }

    return 0;
}
EOF
./compile.sh
./executable -v
./executable -h
./executable simple.c
./executable -E simple.c
"}

