int main(int argc, char **argv) {
    int i;
    int preprocess_only = 0;
    int compile_only = 0;
    int bench = 0;
    int verbose = 0;
    char *outfile = NULL;
    char *infiles[100];
    int infile_count = 0;

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--version") == 0) {
            print_version();
            return 0;
        } else if (strcmp(argv[i], "-vv") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-h") == 0) {
            print_help();
            return 0;
        } else if (strcmp(argv[i], "-E") == 0) {
            preprocess_only = 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            compile_only = 1;
        } else if (strcmp(argv[i], "-bench") == 0) {
            bench = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            if (i + 1 < argc) outfile = argv[++i];
        } else if (strncmp(argv[i], "-D", 2) == 0) {
            char *name = argv[i] + 2;
            char *val = strchr(name, '=');
            if (val) {
                *val = '\0';
                add_macro(name, val + 1);
                *val = '=';
            } else {
                add_macro(name, "1");
            }
        } else if (argv[i][0] == '-') {
            // Ignore other flags
        } else {
            infiles[infile_count++] = argv[i];
        }
    }

    if (infile_count == 0 && !verbose) {
        fprintf(stderr, "tcc: error: no input files\n");
        return 1;
    }

    if (verbose) {
        print_version();
        printf("-> /usr/lib/x86_64-linux-gnu/crt1.o\n");
        printf("-> /usr/lib/x86_64-linux-gnu/crti.o\n");
        for (i = 0; i < infile_count; i++) printf("-> %s\n", infiles[i]);
    }

