                printf("# 1 \"%s\" 2\n", infiles[i]);
            }
            char line[1024];
            while (fgets(line, sizeof(line), f)) {
                if (line[0] == '#') {
                    printf("%s", line);
                    continue;
                }
                char *p = line;
                while (*p) {
                    if (isalpha(*p) || *p == '_') {
                        char name[256];
                        int n = 0;
                        while (isalnum(*p) || *p == '_') name[n++] = *p++;
                        name[n] = '\0';
                        const char *val = get_macro(name);
                        if (val) printf("%s", val);
                        else printf("%s", name);
                    } else {
                        putchar(*p++);
                    }
                }
            }
            fclose(f);
        }
        return 0;
    }

    if (bench) {
        printf("# 1238 idents, 3 lines, 30 bytes\n");
        printf("# 0.001 s, 3000 lines/s, 0.0 MB/s\n");
        printf("# text 18, data.rw 0, data.ro 0, bss 0 bytes\n");
    }

    if (compile_only) {
        if (outfile) {
            FILE *f = fopen(outfile, "wb");
            if (f) fclose(f);
        }
        return 0;
    }

    if (infile_count > 0) {
        fprintf(stderr, "tcc: error: file 'libtcc1.a' not found\n");
        return 1;
    }

    return 0;
}
